package com.bonbio.service;
import com.bonbio.dto.Dtos.*; import com.bonbio.entity.*; import com.bonbio.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.util.List;
@Service public class ProduitService { private final ProduitRepository repo; private final CategorieRepository categories; private final ProductImageService images; public ProduitService(ProduitRepository repo,CategorieRepository categories,ProductImageService images){this.repo=repo;this.categories=categories;this.images=images;} @Transactional(readOnly=true) public List<ProduitResponse> all(){return repo.findAll().stream().map(this::out).toList();} @Transactional(readOnly=true) public ProduitResponse one(Long id){return out(repo.findById(id).orElseThrow(()->new RuntimeException("Produit introuvable.")));} @Transactional public ProduitResponse save(Long id,ProduitRequest r,MultipartFile image){Produit p=id==null?new Produit():repo.findById(id).orElseThrow(()->new RuntimeException("Produit introuvable."));p.setNom(r.nom());p.setPrix(r.prix());p.setDescription(r.description());p.setCategorie(categories.findById(r.categorieId()).orElseThrow(()->new IllegalArgumentException("Catégorie introuvable.")));if(image!=null&&!image.isEmpty())p.setPhotoUrl(images.store(image));else if(id==null)p.setPhotoUrl(null);return out(repo.save(p));} public void delete(Long id){repo.deleteById(id);} private ProduitResponse out(Produit p){return new ProduitResponse(p.getId(),p.getNom(),p.getPrix(),p.getPhotoUrl(),p.getDescription(),new CategorieResponse(p.getCategorie().getId(),p.getCategorie().getNom()));} }
